create function pg_temp.change_week(action text,changes jsonb default '[]',reason text default null,actor uuid default 'ef000000-0000-4000-8000-000000000001',revision integer default null,request uuid default gen_random_uuid()) returns integer language sql as $$
 select public.save_match_workflow(actor,'ef000000-0000-4000-8000-000000000004','ef000000-0000-4000-8000-000000000005','ef000000-0000-4000-8000-000000000006',coalesce(revision,(select w.revision from public.match_workflows w where match_id='ef000000-0000-4000-8000-000000000006'),0),request,action,changes,reason);
$$;
set local role authenticated; set local request.jwt.claim.sub='ef000000-0000-4000-8000-000000000002';
select throws_ok($test$select public.get_match_workflow('ef000000-0000-4000-8000-000000000004','ef000000-0000-4000-8000-000000000005','ef000000-0000-4000-8000-000000000006')$test$,'42501','NOT_AUTHORIZED','viewer cannot load invitations');
select throws_ok($test$select pg_temp.change_week('start')$test$,'42501','permission denied for function save_match_workflow','authenticated cannot mutate directly');
select results_eq($test$select count(*)::integer from public.match_workflows$test$,array[0],'viewer RLS hides workflow metadata');
set local role anon;
select throws_ok($test$select public.get_match_workflow('ef000000-0000-4000-8000-000000000004','ef000000-0000-4000-8000-000000000005','ef000000-0000-4000-8000-000000000006')$test$,'42501','permission denied for function get_match_workflow','anonymous cannot load invitation data');
reset role; set local role service_role; set local request.jwt.claims='{"role":"service_role"}';
select throws_ok($test$select pg_temp.change_week('start','[]',null,'ef000000-0000-4000-8000-000000000002')$test$,'42501','NOT_AUTHORIZED','viewer actor is denied');
select throws_ok($test$select pg_temp.change_week('start','[]',null,'ef000000-0000-4000-8000-000000000003')$test$,'42501','NOT_AUTHORIZED','outsider actor is denied');
select lives_ok($test$select pg_temp.change_week('start')$test$,'start preserves the plan');
select results_eq($test$select response from public.match_calls where match_id='ef000000-0000-4000-8000-000000000006' and player_id='ef000000-0000-4000-8000-000000000116'$test$,array['uninvited'::text],'legacy extra plan does not imply external invitation');
reset role;
select ok(not (private.player_match_totals('ef000000-0000-4000-8000-000000000116')->>'historyComplete')::boolean,'unknown history is explicitly marked incomplete');
set local role service_role;

select throws_ok($test$update public.match_players set played=true where match_id='ef000000-0000-4000-8000-000000000006'$test$,'P0001','FROZEN_MATCH_PLAN','legacy writes cannot change frozen plan');
select throws_ok($test$select pg_temp.change_week('responses','[null]')$test$,'P0001','INVALID_WORKFLOW','malformed payload rejected');
select lives_ok($test$select pg_temp.change_week('responses','[{"playerId":"ef000000-0000-4000-8000-000000000101","response":"pending"},{"playerId":"ef000000-0000-4000-8000-000000000102","response":"pending"},{"playerId":"ef000000-0000-4000-8000-000000000103","response":"pending"},{"playerId":"ef000000-0000-4000-8000-000000000104","response":"pending"},{"playerId":"ef000000-0000-4000-8000-000000000105","response":"pending"},{"playerId":"ef000000-0000-4000-8000-000000000106","response":"pending"},{"playerId":"ef000000-0000-4000-8000-000000000107","response":"pending"},{"playerId":"ef000000-0000-4000-8000-000000000108","response":"pending"},{"playerId":"ef000000-0000-4000-8000-000000000109","response":"pending"},{"playerId":"ef000000-0000-4000-8000-000000000110","response":"pending"}]')$test$,'ten pending calls reserve ten places');
select throws_ok($test$select pg_temp.change_week('responses','[{"playerId":"ef000000-0000-4000-8000-000000000111","response":"pending"}]')$test$,'P0001','ROSTER_CAPACITY','eleventh reserved place rejected');
select results_eq($test$select count(*)::integer from public.match_calls where match_id='ef000000-0000-4000-8000-000000000006' and response='pending'$test$,array[10],'capacity failure leaves entire batch unchanged');
select lives_ok($test$select pg_temp.change_week('responses','[{"playerId":"ef000000-0000-4000-8000-000000000101","response":"declined"},{"playerId":"ef000000-0000-4000-8000-000000000102","response":"declined"},{"playerId":"ef000000-0000-4000-8000-000000000103","response":"declined"},{"playerId":"ef000000-0000-4000-8000-000000000104","response":"declined"},{"playerId":"ef000000-0000-4000-8000-000000000105","response":"declined"},{"playerId":"ef000000-0000-4000-8000-000000000106","response":"declined"}]')$test$,'six declines release six places without replacement pairs');
select lives_ok($test$select pg_temp.change_week('responses','[{"playerId":"ef000000-0000-4000-8000-000000000107","response":"accepted"},{"playerId":"ef000000-0000-4000-8000-000000000108","response":"accepted"},{"playerId":"ef000000-0000-4000-8000-000000000109","response":"accepted"},{"playerId":"ef000000-0000-4000-8000-000000000110","response":"accepted"}]')$test$,'four regular players accept');
select lives_ok($test$select pg_temp.change_week('responses','[{"playerId":"ef000000-0000-4000-8000-000000000111","response":"accepted"},{"playerId":"ef000000-0000-4000-8000-000000000112","response":"accepted"},{"playerId":"ef000000-0000-4000-8000-000000000113","response":"accepted"},{"playerId":"ef000000-0000-4000-8000-000000000114","response":"accepted"},{"playerId":"ef000000-0000-4000-8000-000000000115","response":"accepted"}]')$test$,'five extra players accept');
select throws_ok($test$select pg_temp.change_week('responses','[{"playerId":"ef000000-0000-4000-8000-000000000116","response":"pending"}]',null,'ef000000-0000-4000-8000-000000000001',0)$test$,'P0001','STALE_WORKFLOW','stale update is rejected');
select lives_ok($test$select pg_temp.change_week('responses','[{"playerId":"ef000000-0000-4000-8000-000000000116","response":"pending"}]')$test$,'one pending extra takes remaining place');
select throws_ok($test$select pg_temp.change_week('lock','["ef000000-0000-4000-8000-000000000107","ef000000-0000-4000-8000-000000000108","ef000000-0000-4000-8000-000000000109","ef000000-0000-4000-8000-000000000110","ef000000-0000-4000-8000-000000000111","ef000000-0000-4000-8000-000000000112","ef000000-0000-4000-8000-000000000113","ef000000-0000-4000-8000-000000000114","ef000000-0000-4000-8000-000000000115"]')$test$,'P0001','UNRESOLVED_RESPONSES','pending answers prevent accidental lock');
select lives_ok($test$select pg_temp.change_week('responses','[{"playerId":"ef000000-0000-4000-8000-000000000116","response":"withdrawn"}]')$test$,'withdrawn invitation releases place');
select throws_ok($test$select pg_temp.change_week('lock','[]')$test$,'P0001','INVALID_WORKFLOW','zero participants rejected');
select throws_ok($test$select pg_temp.change_week('lock','["ef000000-0000-4000-8000-000000000999"]')$test$,'P0001','INVALID_WORKFLOW','unknown player cannot participate');
select lives_ok($test$select pg_temp.change_week('lock','["ef000000-0000-4000-8000-000000000107","ef000000-0000-4000-8000-000000000108","ef000000-0000-4000-8000-000000000109","ef000000-0000-4000-8000-000000000110","ef000000-0000-4000-8000-000000000111","ef000000-0000-4000-8000-000000000112","ef000000-0000-4000-8000-000000000113","ef000000-0000-4000-8000-000000000114","ef000000-0000-4000-8000-000000000115"]',null,'ef000000-0000-4000-8000-000000000001',null,'ef000000-0000-4000-8000-000000000900')$test$,'nine participants are locked atomically');
select lives_ok($test$select pg_temp.change_week('lock','["ef000000-0000-4000-8000-000000000107","ef000000-0000-4000-8000-000000000108","ef000000-0000-4000-8000-000000000109","ef000000-0000-4000-8000-000000000110","ef000000-0000-4000-8000-000000000111","ef000000-0000-4000-8000-000000000112","ef000000-0000-4000-8000-000000000113","ef000000-0000-4000-8000-000000000114","ef000000-0000-4000-8000-000000000115"]',null,'ef000000-0000-4000-8000-000000000001',0,'ef000000-0000-4000-8000-000000000900')$test$,'identical retry converges despite stale revision');
select throws_ok($test$select pg_temp.change_week('lock','["ef000000-0000-4000-8000-000000000107"]',null,'ef000000-0000-4000-8000-000000000001',0,'ef000000-0000-4000-8000-000000000900')$test$,'P0001','REQUEST_CONFLICT','changed payload cannot reuse request');
select results_eq($test$select count(*)::integer from public.match_calls where match_id='ef000000-0000-4000-8000-000000000006' and offered_regular$test$,array[10],'all ten regular offers survive declines');
select results_eq($test$select count(*)::integer from public.match_participation where match_id='ef000000-0000-4000-8000-000000000006' and selection_type='regular'$test$,array[4],'four actual regular players');
select results_eq($test$select count(*)::integer from public.match_participation where match_id='ef000000-0000-4000-8000-000000000006' and selection_type='extra'$test$,array[5],'five actual extras');
select throws_ok($test$select pg_temp.change_week('correct','["ef000000-0000-4000-8000-000000000107","ef000000-0000-4000-8000-000000000108","ef000000-0000-4000-8000-000000000109","ef000000-0000-4000-8000-000000000110","ef000000-0000-4000-8000-000000000111","ef000000-0000-4000-8000-000000000112","ef000000-0000-4000-8000-000000000113","ef000000-0000-4000-8000-000000000114","ef000000-0000-4000-8000-000000000115"]')$test$,'P0001','INVALID_WORKFLOW','correction requires reason');
select lives_ok($test$select pg_temp.change_week('correct','["ef000000-0000-4000-8000-000000000107"]','Synthetic correction')$test$,'smaller corrected attendance accepted');
select results_eq($test$select count(*)::integer from public.match_workflow_events where match_id='ef000000-0000-4000-8000-000000000006' and action='correct' and reason='Synthetic correction'$test$,array[1],'correction history recorded exactly once');
reset role;
select results_eq($test$select sum((private.player_match_totals(id)->>'completedExtra')::integer)::integer from public.players where team_id='ef000000-0000-4000-8000-000000000004'$test$,array[0],'corrected extra totals use new attendance only');
set local role authenticated;set local request.jwt.claim.sub='ef000000-0000-4000-8000-000000000001';
select ok(exists(select 1 from jsonb_array_elements(public.get_match_workflow('ef000000-0000-4000-8000-000000000004','ef000000-0000-4000-8000-000000000005','ef000000-0000-4000-8000-000000000008')->'players') p where p->>'id'='ef000000-0000-4000-8000-000000000117'),'inactive historical recipient without selection is available for confirmation');
select throws_ok($test$select public.get_regular_allocation_source('ef000000-0000-4000-8000-000000000004','ef000000-0000-4000-8000-000000000005',now())$test$,'P0001','HISTORY_REVIEW_REQUIRED','unknown historical invitations block generator');
reset role;set local role service_role;set local request.jwt.claims='{"role":"service_role"}';
select lives_ok($test$select public.save_match_workflow('ef000000-0000-4000-8000-000000000001','ef000000-0000-4000-8000-000000000004','ef000000-0000-4000-8000-000000000005','ef000000-0000-4000-8000-000000000008',0,'ef000000-0000-4000-8000-000000000901','history','[{"playerId":"ef000000-0000-4000-8000-000000000101","response":"withdrawn"}]')$test$,'coach confirms historical offers without changing played data');
reset role;set local role authenticated;set local request.jwt.claim.sub='ef000000-0000-4000-8000-000000000001';
select results_eq($test$select jsonb_array_length(public.get_regular_allocation_source('ef000000-0000-4000-8000-000000000004','ef000000-0000-4000-8000-000000000005',now())->'source'->'matches')$test$,array[1],'only unstarted future match is regenerated');
set local request.jwt.claim.sub='ef000000-0000-4000-8000-000000000002';
select ok(not (public.get_match_roster('ef000000-0000-4000-8000-000000000004','ef000000-0000-4000-8000-000000000005','ef000000-0000-4000-8000-000000000006')::text ~ 'level|response|offeredRegular'),'viewer roster contains no private statistics');
reset role;
select ok((select before_state->'participation' <> after_state->'participation' from public.match_workflow_events where match_id='ef000000-0000-4000-8000-000000000006' and action='correct'),'audit retains actual before and after attendance');
select ok((private.player_match_totals('ef000000-0000-4000-8000-000000000116')->>'historyComplete')::boolean,'offers are marked complete after historical confirmation');
select * from finish();
rollback;
